// Парсинг ответа ИИ + fallback. Зеркало collector/classifier_parse.py.
// Никогда не бросает: при кривом ответе модели is_order=false.
const VALID_URGENCY = new Set(['low', 'medium', 'high']);

function extractJson(raw) {
  if (!raw) return null;
  const fenced = raw.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/);
  if (fenced) return fenced[1];
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start !== -1 && end !== -1 && end > start) return raw.slice(start, end + 1);
  return null;
}

function toFloatOrNull(v) {
  if (v === null || v === undefined) return null;
  if (typeof v === 'number') return v;
  if (typeof v === 'string') {
    const digits = v.replace(/,/g, '.').replace(/[^\d.]/g, '');
    if (digits === '' || digits === '.') return null;
    const n = parseFloat(digits);
    return Number.isNaN(n) ? null : n;
  }
  return null;
}

function toStrList(v) {
  if (Array.isArray(v)) return v.map((x) => String(x).trim().toLowerCase()).filter(Boolean);
  if (typeof v === 'string' && v.trim()) return [v.trim().toLowerCase()];
  return [];
}

function parseOutput(raw) {
  const def = { is_order: false, service_type: null, summary: null, budget: null, urgency: 'low', languages: [], skills_required: [] };
  const blob = extractJson(raw);
  if (!blob) return def;
  let data;
  try { data = JSON.parse(blob); } catch (e) { return def; }
  if (typeof data !== 'object' || data === null || Array.isArray(data)) return def;
  const urgency = String(data.urgency || 'low').trim().toLowerCase();
  const st = data.service_type;
  const summary = data.summary;
  return {
    is_order: Boolean(data.is_order),
    service_type: (st && st !== 'null') ? String(st).trim() : null,
    summary: (summary && summary !== 'null') ? String(summary).trim() : null,
    budget: toFloatOrNull(data.budget),
    urgency: VALID_URGENCY.has(urgency) ? urgency : 'low',
    languages: toStrList(data.languages),
    skills_required: toStrList(data.skills_required),
  };
}

const out = [];
for (const item of $input.all()) {
  const src = item.json;
  const rawOutput = typeof src.output === 'string' ? src.output : JSON.stringify(src.output || '');
  const parsed = parseOutput(rawOutput);
  const meta = $('Get Pending').itemMatching(out.length) ? $('Get Pending').itemMatching(out.length).json : src;
  out.push({
    json: {
      raw_message_id: meta.id,
      source_chat: meta.chat,
      author_username: meta.author,
      raw_text: meta.text,
      message_link: meta.message_link,
      ...parsed,
    },
  });
}
return out;
